// One search per location. Separate locations with new lines or ";"
// (commas are allowed inside a location, e.g. "Austin, Texas").
const form = $input.first().json;
const term = String(form['Search term'] || 'HVAC contractor').trim();
const locations = String(form['Locations'] || '')
  .split(/[\n;]+/)
  .map((s) => s.trim())
  .filter(Boolean);

return [...new Set(locations)].map((location) => ({
  json: { location, query: `${term} in ${location}` },
}));

// Flattens all result pages, removes duplicates and closed businesses,
// and scores each lead for an AI receptionist / missed-call offer.
const items = $input.all();
const seen = new Set();
const out = [];

for (let i = 0; i < items.length; i++) {
  let location = '';
  try {
    location = $('Build Queries').itemMatching(i).json.location;
  } catch (e) {}

  for (const p of items[i].json.places || []) {
    if (!p.id || seen.has(p.id)) continue;
    if (p.businessStatus && p.businessStatus !== 'OPERATIONAL') continue;
    seen.add(p.id);

    const phone = p.nationalPhoneNumber || p.internationalPhoneNumber || '';
    const reviews = Number(p.userRatingCount) || 0;
    const rating = Number(p.rating) || 0;
    const reasons = [];
    let score = 0;

    if (phone) { score += 30; reasons.push('has phone'); }
    if (reviews >= 5 && reviews <= 150) { score += 30; reasons.push('small/medium shop'); }
    else if (reviews > 150 && reviews <= 400) { score += 10; reasons.push('mid-size shop'); }
    else if (reviews > 400) { reasons.push('large company (likely has call center)'); }
    else { reasons.push('very few reviews'); }
    if (p.websiteUri) { score += 20; reasons.push('has website'); }
    if (rating && rating < 4.3) { score += 10; reasons.push('rating could improve'); }

    out.push({
      json: {
        place_id: p.id,
        business_name: (p.displayName && p.displayName.text) || '',
        phone,
        international_phone: p.internationalPhoneNumber || '',
        website: p.websiteUri || '',
        address: p.formattedAddress || '',
        search_location: location,
        rating,
        reviews,
        google_maps_url: p.googleMapsUri || '',
        lead_score: score,
        score_reasons: reasons.join(', '),
      },
    });
  }
}

return out;

// Reads each website's HTML: finds emails and checks whether the business
// already has online booking or a chat widget (if not, they need you more).
const leads = $('Clean + Score').all();
const pages = $input.all();

const BOOKING = /servicetitan|housecallpro|housecall pro|jobber|scheduleengine|book online|schedule online|book now/i;
const CHAT = /podium|birdeye|tawk\.to|livechat|intercom|drift\.com|hs-scripts|smith\.ai|ruby\.com/i;
const JUNK = /\.(png|jpe?g|gif|svg|webp)$|example\.|sentry|wixpress|domain\.com|yourname|email\.com/i;

return leads.map((lead, i) => {
  const page = pages[i] ? pages[i].json : {};
  const html = typeof page.data === 'string' ? page.data : '';
  const l = { ...lead.json };

  const emails = [...new Set(
    (html.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || [])
      .map((e) => e.toLowerCase())
      .filter((e) => !JUNK.test(e))
  )];

  l.email = emails[0] || '';
  l.all_emails = emails.slice(0, 5).join(', ');
  l.website_checked = html.length > 0;
  l.has_online_booking = html ? BOOKING.test(html) : '';
  l.has_chat_widget = html ? CHAT.test(html) : '';

  const reasons = l.score_reasons ? [l.score_reasons] : [];
  if (l.email) { l.lead_score += 10; reasons.push('email found'); }
  if (html && !l.has_online_booking && !l.has_chat_widget) {
    l.lead_score += 10;
    reasons.push('no online booking or chat');
  }
  l.score_reasons = reasons.join(', ');
  l.lead_status = l.lead_score >= 70 ? 'HOT' : l.lead_score >= 40 ? 'WARM' : 'COLD';
  l.scraped_at = new Date().toISOString();

  // Find the site's About / Our Story page for the owner lookup.
  let about = '';
  if (html && l.website) {
    const links = [...html.matchAll(/href=["']([^"'#]+)["']/gi)].map((m) => m[1]);
    const hit = links.find((h) =>
      /about|our-story|who-we-are|our-team|meet-the|family|history/i.test(h) &&
      !/\.(jpe?g|png|gif|pdf|svg)$/i.test(h)
    );
    try {
      if (hit) {
        const u = new URL(hit, l.website);
        if (u.host === new URL(l.website).host) about = u.href;
      }
    } catch (e) {}
  }
  l.about_url = about;
  return { json: l };
});

// Turns the homepage + About page into plain text for the AI owner lookup.
const leads = $('Find Emails + Booking Check').all();
const homes = $('Fetch Website').all();
const abouts = $input.all();

const ENTITIES = { '&nbsp;': ' ', '&amp;': '&', '&#39;': "'", '&quot;': '"', '&rsquo;': "'" };
const toText = (html) => String(html || '')
  .replace(/<(script|style|noscript|svg)[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;|&amp;|&#39;|&quot;|&rsquo;/g, (m) => ENTITIES[m])
  .replace(/\s+/g, ' ')
  .trim();

const SYSTEM = "You extract facts about a local business from its own website text.\nReturn JSON only: {\"owner_name\": \"\", \"owner_title\": \"\", \"other_people\": [{\"name\": \"\", \"title\": \"\"}], \"family_owned\": true|false|null, \"founded_year\": \"\", \"personalization_hook\": \"\"}.\nRules:\n- owner_name = the owner, founder, president or CEO. Copy the name exactly as written in the text.\n- Only use names that appear in the text. Never guess. If unknown, use \"\".\n- family_owned: true only if the text says family-owned/family business or names family members running it; null if not stated.\n- founded_year: 4-digit year only if stated, else \"\".\n- personalization_hook: one short, friendly sentence a salesperson could say on a cold call, based only on facts in the text (years in business, family-owned, awards, community work). \"\" if nothing specific.";

return leads.map((lead, i) => {
  const home = toText(homes[i] && homes[i].json.data);
  const about = lead.json.about_url ? toText(abouts[i] && abouts[i].json.data) : '';
  const pageText = (about ? 'ABOUT PAGE:\n' + about.slice(0, 5000) + '\n\n' : '') +
    (home ? 'HOMEPAGE:\n' + home.slice(0, 4000) : '');

  const json = { ...lead.json, page_text: pageText };
  if (pageText) {
    json.ai_request = {
      model: 'gpt-4o-mini',
      temperature: 0,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: SYSTEM },
        { role: 'user', content: 'Business name: ' + lead.json.business_name + '\n\n' + pageText },
      ],
    };
  }
  return { json };
});

// Keeps only facts the AI found that really appear on the website,
// so owner names are never invented.
const lead = $('Prepare AI Input').item.json;
let ai = {};
try {
  ai = JSON.parse($json.choices[0].message.content);
} catch (e) {}

const text = String(lead.page_text || '').toLowerCase();
const clean = (v) => (v === null || v === undefined ? '' : String(v).trim());
const onPage = (v) => clean(v).length > 2 && text.includes(clean(v).toLowerCase());

const owner = onPage(ai.owner_name) ? clean(ai.owner_name) : '';
const others = (Array.isArray(ai.other_people) ? ai.other_people : [])
  .filter((p) => p && onPage(p.name) && clean(p.name) !== owner)
  .slice(0, 4)
  .map((p) => (clean(p.title) ? clean(p.name) + ' (' + clean(p.title) + ')' : clean(p.name)))
  .join(', ');
const year = /^(18|19|20)\d{2}$/.test(clean(ai.founded_year)) && text.includes(clean(ai.founded_year))
  ? clean(ai.founded_year) : '';

const { page_text, ai_request, ...rest } = lead;
const out = {
  ...rest,
  owner_name: owner,
  owner_title: owner ? clean(ai.owner_title) : '',
  other_people: others,
  family_owned: ai.family_owned === true ? 'yes' : ai.family_owned === false ? 'no' : '',
  founded_year: year,
  personalization_hook: clean(ai.personalization_hook).slice(0, 300),
};

if (owner) {
  out.lead_score += 10;
  out.score_reasons = [out.score_reasons, 'owner name found'].filter(Boolean).join(', ');
  out.lead_status = out.lead_score >= 70 ? 'HOT' : out.lead_score >= 40 ? 'WARM' : 'COLD';
}

return { json: out };

// No website text: keep the lead, with empty owner fields.
return $input.all().map((item) => {
  const { page_text, ai_request, ...rest } = item.json;
  return {
    json: {
      ...rest,
      owner_name: '', owner_title: '', other_people: '',
      family_owned: '', founded_year: '', personalization_hook: '',
    },
  };
});
